import React from 'react';

const Footer = () => {
    return (
        <footer className="bg-dark text-white text-center py-3" style={{position:"sticky"}}>
            <div className="container">
                <div className="row">
                    <h3>The Generics</h3>
                    <div className="col">
                        <a href="#">App</a>
                    </div>
                    <div className="col">
                        <a href="#">youtube</a>
                    </div>
                    <div className="col">
                        <a href="#">Podcast</a>
                    </div>
                </div>
            </div>
        </footer>
    );
};

export default Footer;
